import React, { useState, useEffect } from 'react';
import { Chart } from 'react-google-charts';
import axios from 'axios';
import './Visualization.css';

function Visualization() {
  const [columns, setColumns] = useState([]);
  const [selectedX, setSelectedX] = useState('');
  const [selectedY, setSelectedY] = useState('');
  const [chartType, setChartType] = useState('BarChart');
  const [data, setData] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchColumns = async () => {
      try {
        const response = await axios.get('http://localhost:8000/data/columns');
        setColumns(response.data);
      } catch (err) {
        setError('Failed to load column information');
        console.error(err);
      }
    };
    fetchColumns();
  }, []);

  const generateChart = async () => {
    if (!selectedX || !selectedY) {
      setError('Please select both X and Y axes');
      return;
    }
    
    setIsLoading(true);
    setError(null);
    
    try {
      // In a real app, you would fetch actual aggregated data from your API
      // This is a mock implementation
      const mockData = [
        [selectedX, selectedY],
        ['Group 1', Math.floor(Math.random() * 100)],
        ['Group 2', Math.floor(Math.random() * 100)],
        ['Group 3', Math.floor(Math.random() * 100)],
        ['Group 4', Math.floor(Math.random() * 100)],
      ];
      
      setData(mockData);
    } catch (err) {
      setError('Failed to generate chart');
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="visualization-container">
      <h2>Data Visualization Dashboard</h2>
      
      <div className="controls-panel">
        <div className="control-group">
          <label htmlFor="x-axis">X-Axis:</label>
          <select 
            id="x-axis"
            value={selectedX} 
            onChange={(e) => setSelectedX(e.target.value)}
            className="form-select"
          >
            <option value="">Select column</option>
            {columns.map(col => (
              <option key={col.name} value={col.name}>
                {col.name} ({col.type})
              </option>
            ))}
          </select>
        </div>
        
        <div className="control-group">
          <label htmlFor="y-axis">Y-Axis:</label>
          <select 
            id="y-axis"
            value={selectedY} 
            onChange={(e) => setSelectedY(e.target.value)}
            className="form-select"
          >
            <option value="">Select column</option>
            {columns.map(col => (
              <option key={col.name} value={col.name}>
                {col.name} ({col.type})
              </option>
            ))}
          </select>
        </div>
        
        <div className="control-group">
          <label htmlFor="chart-type">Chart Type:</label>
          <select 
            id="chart-type"
            value={chartType} 
            onChange={(e) => setChartType(e.target.value)}
            className="form-select"
          >
            <option value="BarChart">Bar Chart</option>
            <option value="LineChart">Line Chart</option>
            <option value="PieChart">Pie Chart</option>
            <option value="ScatterChart">Scatter Plot</option>
            <option value="Histogram">Histogram</option>
          </select>
        </div>
        
        <button 
          onClick={generateChart} 
          disabled={isLoading}
          className="generate-btn"
        >
          {isLoading ? 'Generating...' : 'Generate Chart'}
        </button>
      </div>
      
      {error && <div className="error-message">{error}</div>}
      
      <div className="chart-area">
        {isLoading ? (
          <div className="loading-spinner"></div>
        ) : data.length > 0 ? (
          <div className="chart-wrapper">
            <Chart
              chartType={chartType}
              width="100%"
              height="400px"
              data={data}
              options={{
                title: `${selectedY} by ${selectedX}`,
                hAxis: { title: selectedX },
                vAxis: { title: selectedY },
                legend: { position: 'bottom' },
                colors: ['#4285F4']
              }}
            />
          </div>
        ) : (
          <div className="empty-state">
            <p>Select columns and generate a chart to visualize the data</p>
          </div>
        )}
      </div>
    </div>
  );
}

export default Visualization;
